import hashlib
import hmac
import re
import io
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import parse_qs, urlparse
import json
import secrets
import bcrypt

SESSION_SECRET = secrets.token_bytes(32)
USERS_DB = {}
SESSIONS = {}

# Maximum allowed request body size (enforced during parsing to prevent
# unbounded memory allocation / DoS).
MAX_BODY_SIZE = 10 * 1024 * 1024

def create_session(username):
    token = secrets.token_hex(32)
    SESSIONS[token] = {"user": username, "role": "user"}
    return token

def verify_session(token):
    return SESSIONS.get(token)

class ChunkedBodyParser:
    """Parse chunked transfer-encoding bodies for file uploads."""

    def __init__(self, rfile, declared_length=None, max_size=MAX_BODY_SIZE):
        self.rfile = rfile
        self.declared_length = declared_length
        self.max_size = max_size
        self.buffer = bytearray()

    def _read_chunk_size(self, line):
        """Parse chunk size from hex, handling extensions per RFC 7230."""
        # Strip chunk extensions (after semicolon)
        line = line.split(b';')[0].strip()
        # Parse hex value - allow leading zeros and whitespace
        return int(line, 16)

    def read_chunked(self):
        """Read a chunked-encoded body."""
        body = bytearray()
        while True:
            line = self.rfile.readline(65537)
            if not line:
                break
            chunk_size = self._read_chunk_size(line)
            if chunk_size < 0:
                raise ValueError("Invalid chunk size")
            if chunk_size == 0:
                # Read trailing headers
                while True:
                    trailer = self.rfile.readline(65537)
                    if trailer in (b'\r\n', b'\n', b''):
                        break
                break
            # Enforce a cumulative body-size limit during parsing to avoid
            # unbounded memory allocation from attacker-controlled chunk sizes.
            if chunk_size > self.max_size or len(body) + chunk_size > self.max_size:
                raise ValueError("Request body too large")
            chunk_data = self.rfile.read(chunk_size)
            body.extend(chunk_data)
            # Consume trailing CRLF after chunk data
            self.rfile.readline()
        return bytes(body)

    def read_body(self, transfer_encoding, content_length):
        """Determine how to read the body based on headers."""
        if transfer_encoding and 'chunked' in transfer_encoding.lower():
            return self.read_chunked()
        elif content_length is not None:
            length = int(content_length)
            if length < 0:
                raise ValueError("Invalid Content-Length")
            if length > self.max_size:
                raise ValueError("Request body too large")
            return self.rfile.read(length)
        return b''


class RequestNormalizer:
    """Normalize incoming requests before auth processing."""

    @staticmethod
    def normalize_headers(headers_dict):
        """Normalize header names and values."""
        normalized = {}
        for key, value in headers_dict.items():
            # RFC 7230: field values can have optional whitespace
            norm_key = key.strip().lower()
            norm_value = value.strip()
            normalized[norm_key] = norm_value
        return normalized

    @staticmethod
    def resolve_body_length(headers):
        """Resolve ambiguous Content-Length / Transfer-Encoding.

        Per RFC 7230 Section 3.3.3, if both Transfer-Encoding and
        Content-Length are present, the message is malformed.
        We reject such requests to prevent smuggling.
        """
        te = headers.get('transfer-encoding', '')
        cl = headers.get('content-length', None)

        # If both are present, reject the request (RFC 7230 compliance)
        if te and cl is not None:
            raise ValueError("Ambiguous framing: both Transfer-Encoding and Content-Length present")

        if te:
            return 'chunked', None
        return 'identity', cl


class AuthUploadHandler(BaseHTTPRequestHandler):
    """Handle authenticated file uploads with proper body parsing."""

    def do_POST(self):
        path = urlparse(self.path).path

        if path == '/register':
            self._handle_register()
        elif path == '/login':
            self._handle_login()
        elif path == '/upload':
            self._handle_upload()
        elif path == '/admin/promote':
            self._handle_promote()
        else:
            self.send_error(404)

    def _read_request_body(self):
        """Read request body handling both chunked and identity encoding."""
        headers = RequestNormalizer.normalize_headers(
            {k: v for k, v in self.headers.items()}
        )

        try:
            framing, cl = RequestNormalizer.resolve_body_length(headers)
        except ValueError:
            raise ValueError("Malformed request: ambiguous body framing")

        parser = ChunkedBodyParser(self.rfile, declared_length=cl, max_size=MAX_BODY_SIZE)

        te = headers.get('transfer-encoding', '')
        return parser.read_body(te, cl)

    def _handle_register(self):
        try:
            body = self._read_request_body()
        except ValueError:
            self.send_error(400, "Malformed request")
            return
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self.send_error(400, "Invalid JSON")
            return

        username = data.get('username', '')
        password = data.get('password', '')

        if not username or not password or len(password) < 8:
            self.send_error(400, "Invalid credentials")
            return

        if username in USERS_DB:
            self.send_error(409, "User exists")
            return

        hashed = bcrypt.hashpw(password.encode(), bcrypt.gensalt())
        USERS_DB[username] = {"password_hash": hashed, "role": "user"}

        self.send_response(201)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({"status": "created"}).encode())

    def _handle_login(self):
        try:
            body = self._read_request_body()
        except ValueError:
            self.send_error(400, "Malformed request")
            return
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self.send_error(400, "Invalid JSON")
            return

        username = data.get('username', '')
        password = data.get('password', '')

        user = USERS_DB.get(username)
        if not user or not bcrypt.checkpw(password.encode(), user["password_hash"]):
            self.send_error(401, "Invalid credentials")
            return

        token = create_session(username)
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Set-Cookie', f'session={token}; HttpOnly; Secure; SameSite=Strict')
        self.end_headers()
        self.wfile.write(json.dumps({"status": "ok"}).encode())

    def _handle_upload(self):
        session_token = self._get_session_cookie()
        session = verify_session(session_token)
        if not session:
            self.send_error(401, "Unauthorized")
            return

        try:
            body = self._read_request_body()
        except ValueError:
            self.send_error(400, "Malformed request")
            return

        if len(body) > MAX_BODY_SIZE:
            self.send_error(413, "File too large")
            return

        file_hash = hashlib.sha256(body).hexdigest()

        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({
            "status": "uploaded",
            "hash": file_hash,
            "size": len(body),
            "user": session["user"]
        }).encode())

    def _handle_promote(self):
        """Admin-only endpoint to promote users."""
        session_token = self._get_session_cookie()
        session = verify_session(session_token)
        if not session or session.get("role") != "admin":
            self.send_error(403, "Forbidden")
            return

        try:
            body = self._read_request_body()
        except ValueError:
            self.send_error(400, "Malformed request")
            return
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self.send_error(400, "Invalid JSON")
            return

        target = data.get('username', '')
        if target in USERS_DB:
            USERS_DB[target]["role"] = "admin"
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({"status": "promoted"}).encode())
        else:
            self.send_error(404, "User not found")

    def _get_session_cookie(self):
        cookie_header = self.headers.get('Cookie', '')
        for part in cookie_header.split(';'):
            part = part.strip()
            if part.startswith('session='):
                return part[8:]
        return None


